-- Lesson 1: What Custom Fields Are
INSERT INTO public.lessons (module_id, lesson_number, title, slug, content, is_published, sort_order)
SELECT id, 1, 'What Custom Fields Are', 'what-custom-fields-are',
'<h2>Understanding Custom Fields in GoHighLevel</h2><p>Custom Fields are data storage containers attached to specific record types in GoHighLevel. They allow you to extend the default data model and capture information unique to your business needs.</p><h3>Key Characteristics</h3><ul><li><strong>Record-Specific:</strong> Tied to Contacts, Opportunities, or other objects</li><li><strong>Structured Data:</strong> Each field has a defined data type</li><li><strong>Searchable & Filterable:</strong> Segment based on field values</li><li><strong>Reportable:</strong> Appear in reports and dashboards</li></ul><h3>Field Types</h3><table class="table"><tr><th>Type</th><th>Best For</th></tr><tr><td>Text</td><td>Short text entries</td></tr><tr><td>Text Area</td><td>Longer notes</td></tr><tr><td>Number</td><td>Numeric values</td></tr><tr><td>Date</td><td>Calendar dates</td></tr><tr><td>Dropdown</td><td>Predefined options</td></tr><tr><td>Checkbox</td><td>Yes/No values</td></tr></table><h3>Where They Live</h3><p>Settings → Custom Fields → Contact/Company Fields or Opportunity Fields</p>',
true, 1 FROM public.training_modules WHERE week_number = 13 AND year = 2026 AND cycle_number = 1
ON CONFLICT (slug) DO UPDATE SET module_id = EXCLUDED.module_id, lesson_number = EXCLUDED.lesson_number, title = EXCLUDED.title, content = EXCLUDED.content, is_published = EXCLUDED.is_published, sort_order = EXCLUDED.sort_order;

-- Lesson 2: What Custom Values Are
INSERT INTO public.lessons (module_id, lesson_number, title, slug, content, is_published, sort_order)
SELECT id, 2, 'What Custom Values Are', 'what-custom-values-are',
'<h2>Understanding Custom Values in GoHighLevel</h2><p>Custom Values are reusable variables that store information you want to use across multiple workflows, emails, SMS messages, and funnels. Unlike Custom Fields which are tied to specific records, Custom Values are account-level variables.</p><h3>Key Characteristics</h3><ul><li><strong>Account-Level:</strong> Available across your entire sub-account</li><li><strong>Reusable:</strong> Use the same value in multiple places</li><li><strong>Easy to Update:</strong> Change once, updates everywhere</li><li><strong>Merge-Friendly:</strong> Insert using {{custom_values.key}}</li></ul><h3>Types of Custom Values</h3><table class="table"><tr><th>Type</th><th>Description</th></tr><tr><td>Standard</td><td>Fixed text, numbers, or URLs</td></tr><tr><td>Calculated</td><td>Formulas that compute values</td></tr><tr><td>Extracted</td><td>Pull data from other fields</td></tr></table><h3>Where They Live</h3><p>Settings → Custom Values</p><h3>Usage</h3><p>Insert with: <code>{{custom_values.YOUR_VALUE_KEY}}</code></p>',
true, 2 FROM public.training_modules WHERE week_number = 13 AND year = 2026 AND cycle_number = 1
ON CONFLICT (slug) DO UPDATE SET module_id = EXCLUDED.module_id, lesson_number = EXCLUDED.lesson_number, title = EXCLUDED.title, content = EXCLUDED.content, is_published = EXCLUDED.is_published, sort_order = EXCLUDED.sort_order;

-- Lesson 3: Contact vs Opportunity Fields
INSERT INTO public.lessons (module_id, lesson_number, title, slug, content, is_published, sort_order)
SELECT id, 3, 'Contact vs Opportunity Fields', 'contact-vs-opportunity-fields',
'<h2>Contact vs Opportunity Custom Fields</h2><p>Choosing where to store data affects how you segment, report, and automate.</p><h3>Contact Fields</h3><p>Store information about the person/company, regardless of any specific deal.</p><ul><li>Demographics (industry, company size)</li><li>Preferences and interests</li><li>Lead Source, VIP Status</li><li>Data that persists across opportunities</li></ul><h3>Opportunity Fields</h3><p>Store information specific to a particular deal.</p><ul><li>Product/Service Selected</li><li>Contract Terms, Proposal Date</li><li>Competitor Mentioned</li><li>Deal-specific tracking</li></ul><h3>Decision Framework</h3><ol><li>Person attribute? → Contact Field</li><li>Deal detail? → Opportunity Field</li><li>Same for next purchase? → Contact Field</li><li>Differs per deal? → Opportunity Field</li></ol>',
true, 3 FROM public.training_modules WHERE week_number = 13 AND year = 2026 AND cycle_number = 1
ON CONFLICT (slug) DO UPDATE SET module_id = EXCLUDED.module_id, lesson_number = EXCLUDED.lesson_number, title = EXCLUDED.title, content = EXCLUDED.content, is_published = EXCLUDED.is_published, sort_order = EXCLUDED.sort_order;

-- Lesson 4: Create & Use Custom Fields
INSERT INTO public.lessons (module_id, lesson_number, title, slug, content, is_published, sort_order)
SELECT id, 4, 'Create & Use Custom Fields', 'create-use-custom-fields',
'<h2>Creating and Using Custom Fields</h2><h3>Step-by-Step</h3><ol><li>Go to Settings → Custom Fields</li><li>Select Object Type (Contact or Opportunity)</li><li>Click "+ Add Field"</li><li>Configure: Name, Key, Type, Description</li><li>Set options for Dropdown/Multi-select</li><li>Save</li></ol><h3>Using in Workflows</h3><ul><li><strong>Triggers:</strong> When field changes</li><li><strong>Actions:</strong> Update field value</li><li><strong>Branching:</strong> If/Else based on value</li></ul><h3>Using in Communications</h3><p>Insert as merge fields: <code>{{contact.field_name}}</code></p><h3>Best Practices</h3><ul><li>Plan structure before creating</li><li>Use consistent naming (snake_case)</li><li>Document field purposes</li><li>Clean unused fields regularly</li></ul>',
true, 4 FROM public.training_modules WHERE week_number = 13 AND year = 2026 AND cycle_number = 1
ON CONFLICT (slug) DO UPDATE SET module_id = EXCLUDED.module_id, lesson_number = EXCLUDED.lesson_number, title = EXCLUDED.title, content = EXCLUDED.content, is_published = EXCLUDED.is_published, sort_order = EXCLUDED.sort_order;

-- Lesson 5: Create & Use Custom Values
INSERT INTO public.lessons (module_id, lesson_number, title, slug, content, is_published, sort_order)
SELECT id, 5, 'Create & Use Custom Values', 'create-use-custom-values',
'<h2>Creating and Using Custom Values</h2><h3>Step-by-Step</h3><ol><li>Go to Settings → Custom Values</li><li>Choose or create a category</li><li>Click "+ Add Custom Value"</li><li>Enter Name, Key, Value</li><li>Add Description</li><li>Save</li></ol><h3>Calculated Values</h3><p>Use formulas for dynamic content:</p><ul><li><code>{{current_date | add_days: 30}}</code></li><li><code>{{contact.trial_start | add_days: 14}}</code></li></ul><h3>Usage Examples</h3><p>Email: <code>Call us at {{custom_values.company_phone}}</code></p><p>SMS: <code>Book here: {{custom_values.calendar_link}}</code></p><h3>Best Practices</h3><ul><li>Use snake_case for keys</li><li>Group related values</li><li>Use for info that might change</li><li>Review quarterly</li></ul>',
true, 5 FROM public.training_modules WHERE week_number = 13 AND year = 2026 AND cycle_number = 1
ON CONFLICT (slug) DO UPDATE SET module_id = EXCLUDED.module_id, lesson_number = EXCLUDED.lesson_number, title = EXCLUDED.title, content = EXCLUDED.content, is_published = EXCLUDED.is_published, sort_order = EXCLUDED.sort_order;

-- Lesson 6: Common Mistakes
INSERT INTO public.lessons (module_id, lesson_number, title, slug, content, is_published, sort_order)
SELECT id, 6, 'Common Mistakes', 'common-mistakes',
'<h2>Common Mistakes to Avoid</h2><h3>Mistake #1: Using Custom Values for Contact Data</h3><p><strong>Wrong:</strong> Storing "Lead Score" as Custom Value<br><strong>Right:</strong> Use Contact Custom Field</p><h3>Mistake #2: Contact Fields for Deal Data</h3><p><strong>Wrong:</strong> "Proposal Date" on Contact<br><strong>Right:</strong> Use Opportunity Custom Field</p><h3>Mistake #3: Duplicate Fields</h3><p><strong>Wrong:</strong> "Lead Source" AND "How Did You Hear About Us"<br><strong>Right:</strong> Consolidate to one field</p><h3>Mistake #4: Inconsistent Naming</h3><p><strong>Wrong:</strong> lead_source, Lead Status, contactType<br><strong>Right:</strong> Use snake_case consistently</p><h3>Mistake #5: Wrong Field Types</h3><p><strong>Wrong:</strong> Using Text for dates<br><strong>Right:</strong> Use Date or Date/Time type</p><h3>Mistake #6: No Documentation</h3><p><strong>Wrong:</strong> Empty description fields<br><strong>Right:</strong> Document purpose for every field</p>',
true, 6 FROM public.training_modules WHERE week_number = 13 AND year = 2026 AND cycle_number = 1
ON CONFLICT (slug) DO UPDATE SET module_id = EXCLUDED.module_id, lesson_number = EXCLUDED.lesson_number, title = EXCLUDED.title, content = EXCLUDED.content, is_published = EXCLUDED.is_published, sort_order = EXCLUDED.sort_order;

-- Lesson 7: Final Business Project
INSERT INTO public.lessons (module_id, lesson_number, title, slug, content, is_published, sort_order)
SELECT id, 7, 'Final Business Project', 'final-business-project',
'<h2>Module 13 Final Business Project</h2><p>Apply what you have learned about Custom Fields and Custom Values to your business.</p><h3>Project Requirements</h3><h4>Part 1: Custom Fields Setup (50 points)</h4><ol><li>Create 3+ Contact Custom Fields relevant to your business</li><li>Create 2+ Opportunity Custom Fields for deal tracking</li><li>Use appropriate field types for each</li><li>Follow naming conventions (snake_case)</li><li>Add descriptions to all fields</li></ol><h4>Part 2: Custom Values Setup (30 points)</h4><ol><li>Create 5+ Custom Values for your business info</li><li>Include: company name, phone, email, address</li><li>Create 2+ calculated values (dates or extractions)</li><li>Organize into logical categories</li></ol><h4>Part 3: Implementation (20 points)</h4><ol><li>Use Custom Fields in at least one workflow trigger</li><li>Use Custom Values in an email template</li><li>Document your field structure</li></ol><h3>Submission</h3><p>Submit screenshots of:</p><ul><li>Your Custom Fields list</li><li>Your Custom Values categories</li><li>Workflow using fields/values</li><li>Brief documentation of your setup</li></ul><h3>Grading Rubric</h3><table class="table"><tr><th>Criteria</th><th>Points</th></tr><tr><td>Contact Fields created (relevant, proper types)</td><td>25</td></tr><tr><td>Opportunity Fields created (deal-focused)</td><td>25</td></tr><tr><td>Custom Values created (business info)</td><td>20</td></tr><tr><td>Calculated values working</td><td>10</td></tr><tr><td>Workflow implementation</td><td>10</td></tr><tr><td>Documentation & naming conventions</td><td>10</td></tr></table>',
true, 7 FROM public.training_modules WHERE week_number = 13 AND year = 2026 AND cycle_number = 1
ON CONFLICT (slug) DO UPDATE SET module_id = EXCLUDED.module_id, lesson_number = EXCLUDED.lesson_number, title = EXCLUDED.title, content = EXCLUDED.content, is_published = EXCLUDED.is_published, sort_order = EXCLUDED.sort_order;

