  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 13 LIMIT 1;

  -- Lesson 5
  INSERT INTO public.lessons (module_id, lesson_number, title, slug, content, is_published, sort_order, created_at, updated_at)
  VALUES (v_module_id, 5, 'How to Create and Use Custom Values', 'create-use-custom-values', '<div class="space-y-8"><div class="bg-gradient-to-r from-amber-500 to-orange-500 rounded-2xl p-6 text-white shadow-lg"><div class="flex items-center gap-3 mb-3"><div class="w-10 h-10 rounded-xl bg-white/20 flex items-center justify-center"><svg class="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 10V3L4 14h7v7l9-11h-7z"/></svg></div><h3 class="text-lg font-bold">Learning Goal</h3></div><p class="text-white/90 text-lg">Learn the simple setup process for creating Custom Values in LeadProspectrr.</p></div><div class="bg-gradient-to-br from-slate-50 to-blue-50 rounded-2xl p-6 border border-blue-100"><div class="flex items-center gap-3 mb-4"><div class="w-12 h-12 rounded-xl bg-blue-100 flex items-center justify-center"><svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"/><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/></svg></div><h3 class="text-xl font-bold text-slate-900">Creating Custom Values</h3></div><div class="space-y-3"><div class="flex items-center gap-4 bg-white rounded-xl p-4 shadow-sm"><div class="w-12 h-12 rounded-xl bg-blue-100 flex items-center justify-center flex-shrink-0"><span class="font-bold text-blue-700">1</span></div><div><h4 class="font-semibold text-slate-900">Go to Settings</h4><p class="text-sm text-slate-600">Navigate to Settings → Custom Values.</p></div></div><div class="flex items-center gap-4 bg-white rounded-xl p-4 shadow-sm"><div class="w-12 h-12 rounded-xl bg-green-100 flex items-center justify-center flex-shrink-0"><span class="font-bold text-green-700">2</span></div><div><h4 class="font-semibold text-slate-900">New Custom Value</h4><p class="text-sm text-slate-600">Click New Custom Value to start creating.</p></div></div><div class="flex items-center gap-4 bg-white rounded-xl p-4 shadow-sm"><div class="w-12 h-12 rounded-xl bg-cyan-100 flex items-center justify-center flex-shrink-0"><span class="font-bold text-cyan-700">3</span></div><div><h4 class="font-semibold text-slate-900">Give It a Name</h4><p class="text-sm text-slate-600">Give it a clear name that describes what it contains.</p></div></div><div class="flex items-center gap-4 bg-white rounded-xl p-4 shadow-sm"><div class="w-12 h-12 rounded-xl bg-purple-100 flex items-center justify-center flex-shrink-0"><span class="font-bold text-purple-700">4</span></div><div><h4 class="font-semibold text-slate-900">Enter the Value</h4><p class="text-sm text-slate-600">Enter the actual value (URL, email, phone number, etc.).</p></div></div><div class="flex items-center gap-4 bg-white rounded-xl p-4 shadow-sm"><div class="w-12 h-12 rounded-xl bg-green-100 flex items-center justify-center flex-shrink-0"><span class="font-bold text-green-700">5</span></div><div><h4 class="font-semibold text-slate-900">Save</h4><p class="text-sm text-slate-600">Save the Custom Value to make it available.</p></div></div><div class="flex items-center gap-4 bg-white rounded-xl p-4 shadow-sm"><div class="w-12 h-12 rounded-xl bg-indigo-100 flex items-center justify-center flex-shrink-0"><span class="font-bold text-indigo-700">6</span></div><div><h4 class="font-semibold text-slate-900">Use the Picker</h4><p class="text-sm text-slate-600">Insert it with the picker in supported areas like emails and workflows.</p></div></div></div></div><div class="bg-gradient-to-r from-blue-600 to-indigo-600 rounded-2xl p-6 text-white shadow-lg"><div class="flex items-start gap-4"><div class="w-12 h-12 rounded-xl bg-white/20 flex items-center justify-center flex-shrink-0"><svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z"/></svg></div><div><h3 class="text-lg font-bold mb-2">Key Point</h3><p class="text-white/90">Creating Custom Values is a simple 6-step process. Use the picker to insert them—never type tokens manually.</p></div></div></div><div class="bg-white rounded-2xl p-6 border shadow-sm"><h3 class="text-lg font-bold text-slate-900 mb-4 flex items-center gap-2"><svg class="w-5 h-5 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4"/></svg>Action Steps</h3><div class="space-y-3"><div class="flex gap-4"><div class="w-8 h-8 rounded-full bg-blue-100 flex items-center justify-center flex-shrink-0 text-blue-700 font-bold text-sm">1</div><div><h4 class="font-semibold text-slate-900">Navigate to Custom Values</h4><p class="text-sm text-slate-600">Go to Settings → Custom Values and review any existing values in your account.</p></div></div><div class="flex gap-4"><div class="w-8 h-8 rounded-full bg-blue-100 flex items-center justify-center flex-shrink-0 text-blue-700 font-bold text-sm">2</div><div><h4 class="font-semibold text-slate-900">Create Your First Value</h4><p class="text-sm text-slate-600">Create a Custom Value called Main Consultation Link with your booking URL.</p></div></div><div class="flex gap-4"><div class="w-8 h-8 rounded-full bg-blue-100 flex items-center justify-center flex-shrink-0 text-blue-700 font-bold text-sm">3</div><div><h4 class="font-semibold text-slate-900">Identify Usage Places</h4><p class="text-sm text-slate-600">Identify 3 places you could use this Custom Value (email templates, workflows, pages).</p></div></div></div></div></div>', true, 5, NOW(), NOW())
  ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, updated_at = NOW();

  -- Lesson 6
  INSERT INTO public.lessons (module_id, lesson_number, title, slug, content, is_published, sort_order, created_at, updated_at)
  VALUES (v_module_id, 6, 'Common Mistakes to Avoid', 'common-mistakes', '<div class="space-y-8"><div class="bg-gradient-to-r from-amber-500 to-orange-500 rounded-2xl p-6 text-white shadow-lg"><div class="flex items-center gap-3 mb-3"><div class="w-10 h-10 rounded-xl bg-white/20 flex items-center justify-center"><svg class="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 10V3L4 14h7v7l9-11h-7z"/></svg></div><h3 class="text-lg font-bold">Learning Goal</h3></div><p class="text-white/90 text-lg">Keep your setup clean and useful by avoiding common mistakes with Custom Fields and Custom Values.</p></div><div class="bg-gradient-to-br from-slate-50 to-rose-50 rounded-2xl p-6 border border-rose-100"><div class="flex items-center gap-3 mb-4"><div class="w-12 h-12 rounded-xl bg-rose-100 flex items-center justify-center"><svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"/></svg></div><h3 class="text-xl font-bold text-slate-900">Common Mistakes</h3></div><div class="space-y-3"><div class="flex items-center gap-4 bg-white rounded-xl p-4 shadow-sm"><div class="w-12 h-12 rounded-xl bg-rose-100 flex items-center justify-center flex-shrink-0"><svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10"/></svg></div><div><h4 class="font-semibold text-slate-900">Creating Too Many Fields</h4><p class="text-sm text-slate-600">Do not create fields for everything. Focus on information you actually use for segmentation, workflows, or reporting.</p></div></div><div class="flex items-center gap-4 bg-white rounded-xl p-4 shadow-sm"><div class="w-12 h-12 rounded-xl bg-amber-100 flex items-center justify-center flex-shrink-0"><svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/></svg></div><div><h4 class="font-semibold text-slate-900">Using a Field for Company-Wide Info</h4><p class="text-sm text-slate-600">Do not store information that is the same for everyone (like your phone number) in a Custom Field. Use a Custom Value instead.</p></div></div><div class="flex items-center gap-4 bg-white rounded-xl p-4 shadow-sm"><div class="w-12 h-12 rounded-xl bg-purple-100 flex items-center justify-center flex-shrink-0"><svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z"/></svg></div><div><h4 class="font-semibold text-slate-900">Using a Value for Contact-Specific Info</h4><p class="text-sm text-slate-600">Do not store unique information about each contact in a Custom Value. Use a Custom Field instead.</p></div></div><div class="flex items-center gap-4 bg-white rounded-xl p-4 shadow-sm"><div class="w-12 h-12 rounded-xl bg-cyan-100 flex items-center justify-center flex-shrink-0"><svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 7h12m0 0l-4-4m4 4l-4 4m0 6H4m0 0l4 4m-4-4l4-4"/></svg></div><div><h4 class="font-semibold text-slate-900">Mixing Contact and Deal Data</h4><p class="text-sm text-slate-600">Do not put deal-specific information on contacts just because it is easier. Keep them properly separated.</p></div></div><div class="flex items-center gap-4 bg-white rounded-xl p-4 shadow-sm"><div class="w-12 h-12 rounded-xl bg-orange-100 flex items-center justify-center flex-shrink-0"><svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/></svg></div><div><h4 class="font-semibold text-slate-900">Typing Tokens Manually</h4><p class="text-sm text-slate-600">Do not type Custom Value tokens manually. Always use the picker to avoid mistakes.</p></div></div><div class="flex items-center gap-4 bg-white rounded-xl p-4 shadow-sm"><div class="w-12 h-12 rounded-xl bg-blue-100 flex items-center justify-center flex-shrink-0"><svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M7 7h.01M7 3h5c.512 0 1.024.195 1.414.586l7 7a2 2 0 010 2.828l-7 7a2 2 0 01-2.828 0l-7-7A1.994 1.994 0 013 12V7a4 4 0 014-4z"/></svg></div><div><h4 class="font-semibold text-slate-900">Confusing Names</h4><p class="text-sm text-slate-600">Do not name items in a confusing way. Use clear, descriptive names everyone understands.</p></div></div></div></div><div class="bg-gradient-to-r from-blue-600 to-indigo-600 rounded-2xl p-6 text-white shadow-lg"><div class="flex items-start gap-4"><div class="w-12 h-12 rounded-xl bg-white/20 flex items-center justify-center flex-shrink-0"><svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z"/></svg></div><div><h3 class="text-lg font-bold mb-2">Key Point</h3><p class="text-white/90">Avoid these common mistakes: too many fields, wrong tool for the data, mixing record types, typing tokens manually, and confusing names.</p></div></div></div><div class="bg-white rounded-2xl p-6 border shadow-sm"><h3 class="text-lg font-bold text-slate-900 mb-4 flex items-center gap-2"><svg class="w-5 h-5 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4"/></svg>Action Steps</h3><div class="space-y-3"><div class="flex gap-4"><div class="w-8 h-8 rounded-full bg-blue-100 flex items-center justify-center flex-shrink-0 text-blue-700 font-bold text-sm">1</div><div><h4 class="font-semibold text-slate-900">Review Your Current Setup</h4><p class="text-sm text-slate-600">Review your current CRM setup and write down 3 items you would fix based on what you have learned.</p></div></div><div class="flex gap-4"><div class="w-8 h-8 rounded-full bg-blue-100 flex items-center justify-center flex-shrink-0 text-blue-700 font-bold text-sm">2</div><div><h4 class="font-semibold text-slate-900">Identify Misused Fields</h4><p class="text-sm text-slate-600">Find any Custom Fields storing company-wide info that should be Custom Values, or vice versa.</p></div></div><div class="flex gap-4"><div class="w-8 h-8 rounded-full bg-blue-100 flex items-center justify-center flex-shrink-0 text-blue-700 font-bold text-sm">3</div><div><h4 class="font-semibold text-slate-900">Plan Corrections</h4><p class="text-sm text-slate-600">Create a plan to fix the mistakes you have identified, prioritizing the most impactful changes.</p></div></div></div></div></div>', true, 6, NOW(), NOW())
  ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, updated_at = NOW();

  -- Lesson 7
  INSERT INTO public.lessons (module_id, lesson_number, title, slug, content, is_published, sort_order, created_at, updated_at)
  VALUES (v_module_id, 7, 'Final Business Project', 'final-business-project', '<div class="space-y-8"><div class="bg-gradient-to-r from-amber-500 to-orange-500 rounded-2xl p-6 text-white shadow-lg"><div class="flex items-center gap-3 mb-3"><div class="w-10 h-10 rounded-xl bg-white/20 flex items-center justify-center"><svg class="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 10V3L4 14h7v7l9-11h-7z"/></svg></div><h3 class="text-lg font-bold">Learning Goal</h3></div><p class="text-white/90 text-lg">Build a clean Custom Fields and Custom Values setup for your business.</p></div><div class="bg-gradient-to-br from-slate-50 to-blue-50 rounded-2xl p-6 border border-blue-100"><div class="flex items-center gap-3 mb-4"><div class="w-12 h-12 rounded-xl bg-blue-100 flex items-center justify-center"><svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 10V3L4 14h7v7l9-11h-7z"/></svg></div><h3 class="text-xl font-bold text-slate-900">Your Task</h3></div><div class="space-y-3"><div class="flex items-center gap-4 bg-white rounded-xl p-4 shadow-sm"><div class="w-12 h-12 rounded-xl bg-blue-100 flex items-center justify-center flex-shrink-0"><svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4"/></svg></div><div><h4 class="font-semibold text-slate-900">Create a Complete Setup</h4><p class="text-sm text-slate-600">Create a simple setup for your own business with: 5 Custom Fields, 2 Opportunity Custom Fields, and 5 Custom Values.</p></div></div></div></div><div class="bg-gradient-to-br from-slate-50 to-purple-50 rounded-2xl p-6 border border-purple-100"><div class="flex items-center gap-3 mb-4"><div class="w-12 h-12 rounded-xl bg-purple-100 flex items-center justify-center"><svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z"/></svg></div><h3 class="text-xl font-bold text-slate-900">If You Are a Speaker</h3></div><div class="space-y-3"><div class="flex items-center gap-4 bg-white rounded-xl p-4 shadow-sm"><div class="w-12 h-12 rounded-xl bg-blue-100 flex items-center justify-center flex-shrink-0"><svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg></div><div><h4 class="font-semibold text-slate-900">Suggested Contact Fields</h4><p class="text-sm text-slate-600">Event Type, Speaking Topic, Event Date, Referral Source, Follow-Up Status.</p></div></div><div class="flex items-center gap-4 bg-white rounded-xl p-4 shadow-sm"><div class="w-12 h-12 rounded-xl bg-cyan-100 flex items-center justify-center flex-shrink-0"><svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13.828 10.172a4 4 0 00-5.656 0l-4 4a4 4 0 105.656 5.656l1.102-1.101m-.758-4.899a4 4 0 005.656 0l4-4a4 4 0 00-5.656-5.656l-1.1 1.1"/></svg></div><div><h4 class="font-semibold text-slate-900">Suggested Custom Values</h4><p class="text-sm text-slate-600">Main booking link, Speaker one-sheet link, Media page URL, Office phone number, Standard sign-off.</p></div></div></div></div><div class="bg-gradient-to-br from-slate-50 to-green-50 rounded-2xl p-6 border border-green-100"><div class="flex items-center gap-3 mb-4"><div class="w-12 h-12 rounded-xl bg-green-100 flex items-center justify-center"><svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z"/></svg></div><h3 class="text-xl font-bold text-slate-900">If You Are a Coach or Consultant</h3></div><div class="space-y-3"><div class="flex items-center gap-4 bg-white rounded-xl p-4 shadow-sm"><div class="w-12 h-12 rounded-xl bg-blue-100 flex items-center justify-center flex-shrink-0"><svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg></div><div><h4 class="font-semibold text-slate-900">Suggested Contact Fields</h4><p class="text-sm text-slate-600">Service Interested In, Business Stage, Budget Range, Referral Source, Preferred Contact Method.</p></div></div><div class="flex items-center gap-4 bg-white rounded-xl p-4 shadow-sm"><div class="w-12 h-12 rounded-xl bg-cyan-100 flex items-center justify-center flex-shrink-0"><svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13.828 10.172a4 4 0 00-5.656 0l-4 4a4 4 0 105.656 5.656l1.102-1.101m-.758-4.899a4 4 0 005.656 0l4-4a4 4 0 00-5.656-5.656l-1.1 1.1"/></svg></div><div><h4 class="font-semibold text-slate-900">Suggested Custom Values</h4><p class="text-sm text-slate-600">Discovery call link, Support email, Company phone number, Client portal URL, Pricing page URL.</p></div></div></div></div><div class="bg-gradient-to-br from-slate-50 to-amber-50 rounded-2xl p-6 border border-amber-100"><div class="flex items-center gap-3 mb-4"><div class="w-12 h-12 rounded-xl bg-amber-100 flex items-center justify-center"><svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"/><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/></svg></div><h3 class="text-xl font-bold text-slate-900">If You Are a Service Business</h3></div><div class="space-y-3"><div class="flex items-center gap-4 bg-white rounded-xl p-4 shadow-sm"><div class="w-12 h-12 rounded-xl bg-blue-100 flex items-center justify-center flex-shrink-0"><svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg></div><div><h4 class="font-semibold text-slate-900">Suggested Contact Fields</h4><p class="text-sm text-slate-600">Service Requested, Service Area, Estimate Needed, Lead Source, Project Date.</p></div></div><div class="flex items-center gap-4 bg-white rounded-xl p-4 shadow-sm"><div class="w-12 h-12 rounded-xl bg-cyan-100 flex items-center justify-center flex-shrink-0"><svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13.828 10.172a4 4 0 00-5.656 0l-4 4a4 4 0 105.656 5.656l1.102-1.101m-.758-4.899a4 4 0 005.656 0l4-4a4 4 0 00-5.656-5.656l-1.1 1.1"/></svg></div><div><h4 class="font-semibold text-slate-900">Suggested Custom Values</h4><p class="text-sm text-slate-600">Quote request link, Main office number, Support email, Review link, Payment page URL.</p></div></div></div></div><div class="bg-gradient-to-r from-blue-600 to-indigo-600 rounded-2xl p-6 text-white shadow-lg"><div class="flex items-start gap-4"><div class="w-12 h-12 rounded-xl bg-white/20 flex items-center justify-center flex-shrink-0"><svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z"/></svg></div><div><h3 class="text-lg font-bold mb-2">Key Point</h3><p class="text-white/90">Create a complete setup tailored to your business type. Start with the suggested fields and values, then customize for your specific needs.</p></div></div></div><div class="bg-white rounded-2xl p-6 border shadow-sm"><h3 class="text-lg font-bold text-slate-900 mb-4 flex items-center gap-2"><svg class="w-5 h-5 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4"/></svg>Action Steps</h3><div class="space-y-3"><div class="flex gap-4"><div class="w-8 h-8 rounded-full bg-blue-100 flex items-center justify-center flex-shrink-0 text-blue-700 font-bold text-sm">1</div><div><h4 class="font-semibold text-slate-900">Choose Your Business Type</h4><p class="text-sm text-slate-600">Identify whether you are a speaker, coach/consultant, or service business to use the appropriate suggestions.</p></div></div><div class="flex gap-4"><div class="w-8 h-8 rounded-full bg-blue-100 flex items-center justify-center flex-shrink-0 text-blue-700 font-bold text-sm">2</div><div><h4 class="font-semibold text-slate-900">Create Your Custom Fields</h4><p class="text-sm text-slate-600">Create 5 Contact Custom Fields based on the suggestions for your business type.</p></div></div><div class="flex gap-4"><div class="w-8 h-8 rounded-full bg-blue-100 flex items-center justify-center flex-shrink-0 text-blue-700 font-bold text-sm">3</div><div><h4 class="font-semibold text-slate-900">Create Your Opportunity Fields</h4><p class="text-sm text-slate-600">Create 2 Opportunity Custom Fields for deal-specific information.</p></div></div><div class="flex gap-4"><div class="w-8 h-8 rounded-full bg-blue-100 flex items-center justify-center flex-shrink-0 text-blue-700 font-bold text-sm">4</div><div><h4 class="font-semibold text-slate-900">Create Your Custom Values</h4><p class="text-sm text-slate-600">Create 5 Custom Values for reusable business information you use repeatedly.</p></div></div></div></div></div>', true, 7, NOW(), NOW())
  ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, updated_at = NOW();

  RAISE NOTICE 'All Module 13 lessons created';
END $$;

-- Quizzes for Lessons 5-7
INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
SELECT id, 'What is the first step to create a Custom Value?', '["Open an email template", "Go to Settings → Custom Values", "Create a workflow", "Edit a contact record"]'::jsonb, 'Go to Settings → Custom Values', 'To create a Custom Value, start by navigating to Settings → Custom Values in the main menu.', 1 FROM public.lessons WHERE slug = 'create-use-custom-values' ON CONFLICT DO NOTHING;

INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
SELECT id, 'How should you insert a Custom Value into an email or workflow?', '["Type the token manually", "Use the picker", "Copy and paste from another email", "Ask an admin to insert it"]'::jsonb, 'Use the picker', 'Always use the picker to insert Custom Values. This ensures the correct token is inserted and reduces errors.', 2 FROM public.lessons WHERE slug = 'create-use-custom-values' ON CONFLICT DO NOTHING;

INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
SELECT id, 'What happens when you update a Custom Value''s content?', '["Only new records get the updated value", "Every place using it automatically shows the new value", "You have to manually update each email template", "It only updates in workflows"]'::jsonb, 'Every place using it automatically shows the new value', 'When you update a Custom Value, every email, workflow, page, or template that uses it will automatically display the new value.', 3 FROM public.lessons WHERE slug = 'create-use-custom-values' ON CONFLICT DO NOTHING;

INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
SELECT id, 'Which is a mistake when using Custom Fields and Custom Values?', '["Using the picker to insert Custom Values", "Storing your company phone number in a Custom Field on every contact", "Creating fields for information you actually use", "Naming fields clearly"]'::jsonb, 'Storing your company phone number in a Custom Field on every contact', 'Storing company-wide information in a Custom Field is a mistake. This should be stored as a Custom Value instead.', 1 FROM public.lessons WHERE slug = 'common-mistakes' ON CONFLICT DO NOTHING;

INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
SELECT id, 'Why shouldn''t you type Custom Value tokens manually?', '["Because it''s slower", "Because you might make a typo that breaks the token", "Because it''s not allowed", "Because tokens are secret"]'::jsonb, 'Because you might make a typo that breaks the token', 'Typing tokens manually can lead to typos that break the token. Always use the picker.', 2 FROM public.lessons WHERE slug = 'common-mistakes' ON CONFLICT DO NOTHING;

INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
SELECT id, 'What should you do if you have deal-specific information stored on contact records?', '["Leave it there since it''s already set up", "Move it to opportunity fields where it belongs", "Delete the information", "Convert it to a Custom Value"]'::jsonb, 'Move it to opportunity fields where it belongs', 'Deal-specific information should be stored on opportunities, not contacts.', 3 FROM public.lessons WHERE slug = 'common-mistakes' ON CONFLICT DO NOTHING;

INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
SELECT id, 'How many Custom Fields should you create for the final project?', '["2", "5", "10", "Unlimited"]'::jsonb, '5', 'The final project asks you to create 5 Custom Fields for contacts, plus 2 Opportunity Custom Fields, for a total of 7 fields.', 1 FROM public.lessons WHERE slug = 'final-business-project' ON CONFLICT DO NOTHING;

INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
SELECT id, 'What should you do after creating your Custom Fields and Custom Values?', '["Nothing, the setup is complete", "Test them in forms, workflows, and records to ensure they work correctly", "Delete them and start over", "Tell your clients to stop using the CRM"]'::jsonb, 'Test them in forms, workflows, and records to ensure they work correctly', 'After creating your fields and values, you should test them in real scenarios—add them to forms, use them in workflows, and verify they appear correctly on records.', 2 FROM public.lessons WHERE slug = 'final-business-project' ON CONFLICT DO NOTHING;

INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
SELECT id, 'Which business type suggestion includes ''Event Type'' as a recommended Custom Field?', '["Coach or Consultant", "Service Business", "Speaker", "All of the above"]'::jsonb, 'Speaker', 'Event Type is listed as a suggested Contact Field for speakers, along with Speaking Topic, Event Date, Referral Source, and Follow-Up Status.', 3 FROM public.lessons WHERE slug = 'final-business-project' ON CONFLICT DO NOTHING;
